<script>
import { Component, Prop, Vue } from "vue-property-decorator";
import { Fragment } from "vue-fragment";

@Component({
  components: {
    Fragment,
  },
})
export default class IconGraphic extends Vue {
  @Prop({ type: Number }) width;
  @Prop({ type: Number }) height;
  @Prop({ type: [Number, Object], default: () => ({ height: 24 }) }) size;

  get viewBox() {
    return `0 0 ${this.width} ${this.height}`;
  }

  get baseSize() {
    return {
      width: this.width,
      height: this.height,
    };
  }

  get renderSize() {
    const size = this.baseSize;
    const aspect = size.width / size.height;
    let propsSize = this.size;

    if (typeof propsSize === "string") {
      propsSize = Number.parseFloat(size);
    }

    if (typeof propsSize === "number") {
      if (this.baseSize.height > this.baseSize.width) {
        this.renderHeight = propsSize;
        this.renderWidth = this.renderHeight * aspect;
      } else {
        this.renderWidth = propsSize;
        this.renderHeight = this.renderWidth / aspect;
      }
    } else if (propsSize.width === void 0 && propsSize.height === void 0) {
      this.renderWidth = this.baseSize.width;
      this.renderHeight = this.baseSize.height;
    } else if (propsSize.width === void 0) {
      this.renderHeight = propsSize.height;
      this.renderWidth = this.renderHeight * aspect;
    } else if (propsSize.height === void 0) {
      this.renderWidth = propsSize.width;
      this.renderHeight = this.renderWidth / aspect;
    } else {
      this.renderWidth = propsSize.width;
      this.renderHeight = propsSize.height;
    }

    return {
      width: this.renderWidth,
      height: this.renderHeight,
    };
  }

  beforeMount() {
    /**
     * Emits when the graphic is clicked
     *
     * @event click
     */
    this.$emit("onSize", { width: this.width, height: this.height });
  }
}
</script>

<template>
  <svg
    :key="`${renderSize.width}_${renderSize.height}`"
    class="Icon"
    :width="renderSize.width"
    :height="renderSize.height"
    :viewBox="viewBox"
    xmlns="http://www.w3.org/2000/svg"
    preserveAspectRatio="none"
    @click="$emit('click')"
  >
    <slot />
  </svg>
</template>
